const { createClient } = require('@supabase/supabase-js');
const supabase = createClient('https://vgujnkxylipfwmkpwzvb.supabase.co', process.env.SUPABASE_SERVICE_KEY);

// We need a video_id per chapter — get the first video of each chapter
async function getFirstVideoIds(chapterIds) {
  const map = {};
  for (const cid of chapterIds) {
    const { data } = await supabase.from('videos').select('id').eq('chapter_id', cid).order('order_index').limit(1);
    if (data && data.length > 0) map[cid] = data[0].id;
  }
  return map;
}

