async function seedAllQuizzes() {
  const chapterIds = modules.map(m => m.chapterId);
  console.log('Fetching first video IDs for all chapters...');
  const videoMap = await getFirstVideoIds(chapterIds);
  
  let totalQuizzes = 0, totalQuestions = 0, errors = 0;

  for (const mod of modules) {
    const videoId = videoMap[mod.chapterId];
    if (!videoId) { console.error(`❌ No video found for chapter ${mod.chapterId}`); errors++; continue; }

    const { data: quiz, error: quizErr } = await supabase
      .from('quizzes')
      .insert({ chapter_id: mod.chapterId, video_id: videoId, quiz_type: 'mini_video', passing_score: 70 })
      .select()
      .single();

    if (quizErr) { console.error(`❌ Quiz failed: ${mod.chapterId}`, quizErr.message); errors++; continue; }
    totalQuizzes++;

    for (let i = 0; i < mod.questions.length; i++) {
      const q = mod.questions[i];
      const { error: qErr } = await supabase.from('quiz_questions').insert({
        quiz_id: quiz.id,
        question_text: q.q,
        options: q.opts,
        correct_answer_index: q.correct,
        explanation: q.exp,
        order_index: i,
      });
      if (qErr) { console.error(`❌ Q failed:`, qErr.message); errors++; }
      else totalQuestions++;
    }

    process.stdout.write(`\r✅ ${totalQuizzes}/${modules.length} quizzes | ${totalQuestions} questions | ${errors} errors`);
  }

  console.log(`\n\n🎉 Done! ${totalQuizzes} quizzes, ${totalQuestions} questions, ${errors} errors.`);
}

seedAllQuizzes();
